typedef float rational_t;

extern "C" float sqrtf(float);

class vector3d
{
public:
  rational_t x, y, z;

  vector3d() {}
  vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }

  vector3d& operator=(const vector3d& v)
  {
    x = v.x;
    y = v.y;
    z = v.z;
    return *this;
  }

  vector3d& operator/=(rational_t d)
  {
    rational_t d_inv = 1.0f / d;
    x *= d_inv;
    y *= d_inv;
    z *= d_inv;
    return *this;
  }

  rational_t length() const
  {
    return sqrtf(x*x + y*y + z*z);
  }
};

inline vector3d operator-(const vector3d& a, const vector3d& b)
{
  vector3d result;
  result.x = a.x - b.x;
  result.y = a.y - b.y;
  result.z = a.z - b.z;
  return result;
}

class matrix4x4
{
  float data[16];
};

class geometry_manager
{
  char singleton_data[8];

public:
  enum xform_t
  {
    XFORM_LOCAL_TO_WORLD,
    XFORM_WORLD_TO_VIEW
  };

  vector3d camera_pos;
  vector3d camera_up;
  vector3d camera_dir;

  void set_look_at(matrix4x4*, const vector3d&, const vector3d&, const vector3d&);
  void set_xform(xform_t, const matrix4x4&);
  void set_view(const vector3d&, const vector3d&, const vector3d&);
};

extern const vector3d ZVEC;

